use super::*;use std::path::Path;
struct Source(String);impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Ok(self.0.clone())}}
fn observe(text:&str,severity:Severity)->(String,Vec<Diagnostic>){let source=format!("/proc/probe(a)\n{text}");let executor=dm_exec::BuildExecutor::new(1).unwrap();let diagnostic=dm_tree::frontend::build_for_checker_diagnostics(Path::new("unknown-setting.dme"),&Source(source.clone()),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:None,observer:None},None,&executor).unwrap();let view=diagnostic.source_view().unwrap();let body=view.archive().parse(0).unwrap();let rows=archived(&body,severity).unwrap();(source,rows)}
#[test]fn unknown_linter_setting_preserves_initial_prefix_order_duplicate_names_in_relation_and_statement_points(){let(source,rows)=observe("    set SpacemanDMM_typo = 1\n    set SpacemanDMM_typo in 1\n    set SpacemanDMM_return_type = /datum\n    set ordinary_unknown = 1\n    return 1\n    set SpacemanDMM_late = 1\n    if(a)\n        set SpacemanDMM_nested = 1\n",Severity::Warning);assert_eq!(rows.len(),2);assert!(rows.iter().all(|r|r.message=="unknown linter setting \"SpacemanDMM_typo\""&&r.family=="unknown_linter_setting"&&r.severity==Severity::Warning&&r.notes.is_empty()));let starts=source.match_indices("set SpacemanDMM_typo").map(|(at,_)|at).collect::<Vec<_>>();assert_eq!(rows.iter().map(|r|r.span.start).collect::<Vec<_>>(),starts);}
#[test]fn unknown_linter_setting_has_exact_known_set_and_does_not_evaluate_unknown_rhs(){let mut body=String::new();use std::fmt::Write;for name in KNOWN{writeln!(&mut body,"    set {name} = 1").unwrap();}body.push_str("    set SpacemanDMM_return_type = /datum\n    set spacemanDMM_typo = 1\n    set SpacemanDMM_unknown = missing_call()\n");let(_,rows)=observe(&body,Severity::Warning);assert_eq!(rows.len(),1);assert_eq!(rows[0].message,"unknown linter setting \"SpacemanDMM_unknown\"");assert!(observe(&body,Severity::Disabled).1.is_empty());}
#[test]fn unknown_linter_setting_known_names_are_exact_frozen_original_match_arms(){let original=include_str!("checks_unknown_linter_setting_original.reference");let start=original.find("let procdirective = match directive").unwrap();let stop=original[start..].find("other =>").unwrap()+start;let mut old=original[start..stop].lines().filter_map(|line|line.trim().strip_prefix('"').and_then(|tail|tail.split_once('"')).map(|(name,_)|name)).collect::<Vec<_>>();old.sort_unstable();let mut actual=KNOWN.to_vec();actual.sort_unstable();assert_eq!(actual,old);assert!(original.contains("name == \"SpacemanDMM_return_type\""));assert!(original.contains("} else if name.starts_with(\"SpacemanDMM_\")"));assert!(original.contains("} else {\n                break;"));}

fn observe_ordinary(text:&str,severity:Severity)->(String,Vec<Diagnostic>){let source=format!("/proc/probe(a)\n{text}");let executor=dm_exec::BuildExecutor::new(1).unwrap();let diagnostic=dm_tree::frontend::build_for_checker_diagnostics(Path::new("ordinary-unknown-setting.dme"),&Source(source.clone()),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:None,observer:None},None,&executor).unwrap();let view=diagnostic.source_view().unwrap();let body=view.archive().parse(0).unwrap();let rows=archived_ordinary_checked(&body,severity,&mut||Ok(())).unwrap();(source,rows)}
#[test]fn unknown_setting_preserves_original_prefix_order_case_and_never_interprets_rhs(){let(source,rows)=observe_ordinary("    set ordinary_unknown = missing_call()\n    set ordinary_unknown in 1\n    set SpacemanDMM_return_type = /datum\n    set SpacemanDMM_unknown = 1\n    set SpacemanDMMfoo = 1\n    set spacemanDMM_typo = 1\n    return 0\n    set ordinary_late = 1\n    if(a)\n        set ordinary_nested = 1\n",Severity::Warning);assert_eq!(rows.iter().map(|r|r.message.as_str()).collect::<Vec<_>>(),["unknown setting \"ordinary_unknown\"","unknown setting \"ordinary_unknown\"","unknown setting \"SpacemanDMMfoo\"","unknown setting \"spacemanDMM_typo\""]);assert!(rows.iter().all(|r|r.family=="unknown_setting"&&r.severity==Severity::Warning&&r.notes.is_empty()));let starts=source.match_indices("set ").take(6).enumerate().filter_map(|(i,(at,_))|(!matches!(i,2|3)).then_some(at)).collect::<Vec<_>>();assert_eq!(rows.iter().map(|r|r.span.start).collect::<Vec<_>>(),starts);}
#[test]fn unknown_setting_exact_ordinary_registry_matches_pinned_ast_and_does_not_change_linter_family(){let original=include_str!("checks_unknown_setting_names_original.reference");let names=original.lines().filter_map(|line|line.trim().strip_prefix('"').and_then(|tail|tail.split_once('"')).map(|(name,_)|name)).collect::<Vec<_>>();assert_eq!(KNOWN_ORDINARY,names);let mut body=String::new();use std::fmt::Write;for name in KNOWN_ORDINARY{writeln!(&mut body,"    set {name} = 1").unwrap();}assert!(observe_ordinary(&body,Severity::Warning).1.is_empty());body.push_str("    set ordinary_unknown = 1\n    set SpacemanDMM_unknown = 1\n");assert_eq!(observe_ordinary(&body,Severity::Warning).1.len(),1);assert_eq!(observe(&body,Severity::Warning).1.len(),1);assert!(observe_ordinary(&body,Severity::Disabled).1.is_empty());let old=include_str!("checks_unknown_linter_setting_original.reference");assert!(old.contains("} else if !KNOWN_SETTING_NAMES.contains(&name.as_str())"));assert!(old.contains("format!(\"unknown setting {name:?}\")"));}
